import{_ as e,o,c as n,ag as i}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const h=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 9 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 9 из 10","date":"2026-10-10T00:00:00.000Z","source":"https://t.me/jfyi_ps/103","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-9"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 9 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-9"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 9 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 9 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-9\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-10\\"}"]]},"headers":[],"relativePath":"posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-9.md","filePath":"posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-9.md"}'),r={name:"posts/2026-10-10-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-9.md"};function a(p,t,s,l,c,m){return o(),n("div",null,[...t[0]||(t[0]=[i('<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026).**</p><ol start="9"><li>Непрерывная эволюция агентов**</li></ol><p>Хранение опыта в контексте/векторной базе ≠ обучение на нём — нужна активная оценка/сопоставление/обобщение. Не меняй параметры по непроверенной обратной связи — сначала кандидатная версия с регрессией и проверкой безопасности.</p><p>Трёхуровневая проверка траектории: результат (реальное состояние среды) → процесс (разрешённым способом, код) → качество (LLM-as-Judge). Сигнал: статус + вывод по измерению + локализация + метка отказа.</p><p>4 носителя обновления по представимости: факты → база знаний; словесные принципы → Prompt/Skill; детерминированные процессы → программы/Harness; неявное → параметры. Взаимодополняющие. Маршрутизация даёт только предложение, не право на выпуск.</p><p>Опыт→знания: траектория → анализ → обобщённый документ по множеству случаев, с подтверждением несколькими траекториями и положительным переносом.</p><p>Опыт→инструкции: поднимай правило, только когда множество траекторий обнажают одну ошибку. Минимальный diff с источником. Тестируй на граничном И удерживающем наборах — модель может принять дефект за «разумное поведение».</p><p>Опыт→программы: компилируй повторяющиеся траектории в параметризованный код (проверки ДО/ПОСЛЕ + итоговая проверка). Самомодификация — кандидатная ветвь → тесты → регрессия → canary, никогда напрямую.</p><p>Опыт→параметры: решает представимость способности, не стабильность задачи.</p><p>Онлайн-контур (выполнение+фиксация, не меняет агента) отдельно от офлайн (агрегация→диагностика→кандидат→проверка→публикация). Разделяй Harness updating и Harness benefit. Оценивай по 5 категориям: регрессия, обобщение, токены, безопасность, инженерное качество.</p><p>В открытых задачах — разделяй выводы и свидетельства, сохраняй отрицательные результаты и разнообразие веток, переноси человека на уровень постановки проблемы.</p><p>3 границы безопасности: недоверенный источник не пишется в Skill напрямую; кандидатная/официальная зона разделены; запрет самомодификации проверяющих механизмов. «Обучение во сне»: порог → ориентация → сбор → проверка → индексирование.</p><p>Продолжение следует...</p>',13)])])}const u=e(r,[["render",a]]);export{h as __pageData,u as default};
